// ============================================================
// 1. SISTEMA DE USUÁRIO COM PERSISTÊNCIA
// ============================================================

const GDIUserSystem = (() => {
  const STORAGE_PREFIX = 'gdi-user-';
  const CURRENT_USER_KEY = 'gdi-current-user';

  // Obter ID único do usuário
  function getUserId() {
    let userId = localStorage.getItem(CURRENT_USER_KEY);
    if (!userId) {
      userId = 'user-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
      localStorage.setItem(CURRENT_USER_KEY, userId);
    }
    return userId;
  }

  // Salvar notas de um vídeo
  function saveVideoNotes(videoId, notes) {
    const key = STORAGE_PREFIX + 'notes-' + videoId;
    localStorage.setItem(key, JSON.stringify(notes));
  }

  // Recuperar notas de um vídeo
  function getVideoNotes(videoId) {
    const key = STORAGE_PREFIX + 'notes-' + videoId;
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  }

  // Salvar progresso de vídeo
  function saveVideoProgress(videoId, currentTime, duration, fileName) {
    const key = STORAGE_PREFIX + 'progress-' + videoId;
    const progress = {
      currentTime: currentTime,
      duration: duration,
      fileName: fileName,
      lastWatched: new Date().toISOString(),
      percentage: (currentTime / duration) * 100
    };
    localStorage.setItem(key, JSON.stringify(progress));
    updateContinueWatchingList(videoId, progress);
  }

  // Recuperar progresso de vídeo
  function getVideoProgress(videoId) {
    const key = STORAGE_PREFIX + 'progress-' + videoId;
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : null;
  }

  // Salvar preferências do usuário
  function saveUserPreferences(prefs) {
    const key = STORAGE_PREFIX + 'prefs';
    localStorage.setItem(key, JSON.stringify(prefs));
  }

  // Recuperar preferências
  function getUserPreferences() {
    const key = STORAGE_PREFIX + 'prefs';
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : {
      theme: 'dark',
      autoplayNext: true,
      showNotes: true
    };
  }

  // Atualizar lista "Continuar Assistindo"
  function updateContinueWatchingList(videoId, progress) {
    const key = STORAGE_PREFIX + 'continue-watching';
    let list = [];
    const existing = localStorage.getItem(key);
    if (existing) {
      list = JSON.parse(existing);
    }
    
    // Remove se já existe
    list = list.filter(v => v.videoId !== videoId);
    
    // Adiciona no topo (mais recente)
    list.unshift({
      videoId: videoId,
      ...progress
    });
    
    // Manter apenas os últimos 10
    list = list.slice(0, 10);
    
    localStorage.setItem(key, JSON.stringify(list));
  }

  // Obter lista "Continuar Assistindo"
  function getContinueWatchingList() {
    const key = STORAGE_PREFIX + 'continue-watching';
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  }

  return {
    getUserId,
    saveVideoNotes,
    getVideoNotes,
    saveVideoProgress,
    getVideoProgress,
    saveUserPreferences,
    getUserPreferences,
    updateContinueWatchingList,
    getContinueWatchingList
  };
})();

// ============================================================
// 2. PAINEL DE ANOTAÇÕES COM TIMESTAMP
// ============================================================

const NotesPanel = (() => {
  let currentVideoId = null;
  let currentPlayer = null;

  function init(videoId, player) {
    currentVideoId = videoId;
    currentPlayer = player;
    createNotesPanel();
    loadNotes();
  }

  function createNotesPanel() {
    if (document.getElementById('gdi-notes-panel')) return;

    const panelHTML = `
      <div id="gdi-notes-panel" class="gdi-notes-panel" style="display:none;">
        <div class="gdi-notes-header">
          <h3><i class="bi bi-pencil-square"></i> Anotações</h3>
          <button id="gdi-notes-close" class="gdi-btn-close">&times;</button>
        </div>
        <div class="gdi-notes-input-group">
          <textarea id="gdi-notes-text" placeholder="Escreva uma anotação..." rows="3"></textarea>
          <div class="gdi-notes-timestamp">
            <span id="gdi-notes-current-time">00:00</span>
            <button id="gdi-notes-add-btn" class="gdi-btn gdi-btn-primary">
              <i class="bi bi-plus-lg"></i> Adicionar Nota
            </button>
          </div>
        </div>
        <div id="gdi-notes-list" class="gdi-notes-list"></div>
      </div>
    `;

    const style = `
      <style>
        .gdi-notes-panel {
          position: fixed;
          right: 16px;
          top: 70px;
          width: 300px;
          max-height: 500px;
          background: rgba(14, 14, 22, 0.95);
          border: 1.5px solid rgba(255,255,255,0.13);
          border-radius: 12px;
          box-shadow: 0 10px 40px rgba(0,0,0,0.6);
          padding: 16px;
          z-index: 9500;
          overflow-y: auto;
          font-size: 12px;
        }
        .gdi-notes-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 12px;
          border-bottom: 1px solid rgba(255,255,255,0.1);
          padding-bottom: 8px;
        }
        .gdi-notes-header h3 {
          margin: 0;
          font-size: 14px;
          font-weight: 700;
        }
        .gdi-btn-close {
          background: none;
          border: none;
          color: #8b949e;
          font-size: 20px;
          cursor: pointer;
          padding: 0;
        }
        .gdi-btn-close:hover { color: #f0f6fc; }
        .gdi-notes-input-group {
          display: flex;
          flex-direction: column;
          gap: 8px;
          margin-bottom: 12px;
        }
        #gdi-notes-text {
          background: rgba(255,255,255,0.07);
          border: 1px solid rgba(255,255,255,0.13);
          border-radius: 6px;
          color: #f0f6fc;
          padding: 8px;
          font-size: 11px;
          font-family: inherit;
          resize: none;
        }
        #gdi-notes-text::placeholder { color: #8b949e; }
        .gdi-notes-timestamp {
          display: flex;
          gap: 8px;
          align-items: center;
        }
        #gdi-notes-current-time {
          background: rgba(255,255,255,0.1);
          padding: 4px 8px;
          border-radius: 4px;
          font-weight: 700;
          min-width: 45px;
          text-align: center;
        }
        .gdi-notes-list {
          display: flex;
          flex-direction: column;
          gap: 8px;
        }
        .gdi-note-item {
          background: rgba(255,255,255,0.05);
          border-left: 3px solid #1f6feb;
          padding: 8px;
          border-radius: 4px;
          font-size: 11px;
        }
        .gdi-note-timestamp {
          font-weight: 700;
          color: #1f6feb;
          cursor: pointer;
          margin-bottom: 4px;
        }
        .gdi-note-timestamp:hover { color: #58a6ff; }
        .gdi-note-text {
          color: #e6edf3;
          margin-bottom: 4px;
        }
        .gdi-note-delete {
          background: none;
          border: none;
          color: #8b949e;
          font-size: 10px;
          cursor: pointer;
        }
        .gdi-note-delete:hover { color: #ff6b6b; }
      </style>
    `;

    document.head.insertAdjacentHTML('beforeend', style);
    document.body.insertAdjacentHTML('beforeend', panelHTML);

    attachNotesEvents();
  }

  function attachNotesEvents() {
    document.getElementById('gdi-notes-close').addEventListener('click', togglePanel);
    document.getElementById('gdi-notes-add-btn').addEventListener('click', addNote);
    
    // Atualizar tempo atual a cada segundo
    if (currentPlayer) {
      setInterval(updateCurrentTime, 1000);
    }
  }

  function updateCurrentTime() {
    if (!currentPlayer) return;
    
    let currentTime = 0;
    // Detectar tipo de player e obter tempo atual
    if (currentPlayer.currentTime !== undefined) {
      currentTime = currentPlayer.currentTime;
    } else if (typeof currentPlayer.currentTime === 'function') {
      currentTime = currentPlayer.currentTime();
    } else if (window._gdiAPlayer && window._gdiAPlayer.audio) {
      currentTime = window._gdiAPlayer.audio.currentTime;
    }

    const timeStr = formatTimeForNotes(currentTime);
    document.getElementById('gdi-notes-current-time').textContent = timeStr;
  }

  function formatTimeForNotes(seconds) {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = Math.floor(seconds % 60);
    
    if (h > 0) {
      return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    }
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  }

  function addNote() {
    const text = document.getElementById('gdi-notes-text').value.trim();
    if (!text) return;

    const timeStr = document.getElementById('gdi-notes-current-time').textContent;
    
    const notes = GDIUserSystem.getVideoNotes(currentVideoId);
    notes.push({
      id: Date.now(),
      timestamp: timeStr,
      text: text,
      createdAt: new Date().toISOString()
    });

    GDIUserSystem.saveVideoNotes(currentVideoId, notes);
    document.getElementById('gdi-notes-text').value = '';
    loadNotes();
  }

  function loadNotes() {
    const notes = GDIUserSystem.getVideoNotes(currentVideoId);
    const listEl = document.getElementById('gdi-notes-list');
    
    if (notes.length === 0) {
      listEl.innerHTML = '<div style="color:#8b949e;text-align:center;">Nenhuma anotação ainda</div>';
      return;
    }

    listEl.innerHTML = notes.map(note => `
      <div class="gdi-note-item">
        <div class="gdi-note-timestamp" onclick="seekToTimestamp('${note.timestamp}')">${note.timestamp}</div>
        <div class="gdi-note-text">${escHtml(note.text)}</div>
        <button class="gdi-note-delete" onclick="deleteNote(${currentVideoId}, ${note.id})">
          <i class="bi bi-trash"></i> Remover
        </button>
      </div>
    `).join('');
  }

  function togglePanel() {
    const panel = document.getElementById('gdi-notes-panel');
    panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
  }

  return {
    init,
    togglePanel,
    loadNotes
  };
})();

// ============================================================
// 3. BANNER "CONTINUAR ASSISTINDO"
// ============================================================

function renderContinueWatchingBanner() {
  const list = GDIUserSystem.getContinueWatchingList();
  if (list.length === 0) return '';

  return `
    <div class="gdi-continue-watching-banner">
      <h3><i class="bi bi-play-circle"></i> Continuar Assistindo</h3>
      <div class="gdi-cw-items">
        ${list.slice(0, 3).map(item => {
          const progress = item.percentage || 0;
          const timeLeft = item.duration - item.currentTime;
          return `
            <div class="gdi-cw-item">
              <div class="gdi-cw-info">
                <div class="gdi-cw-title">${escHtml(item.fileName)}</div>
                <div class="gdi-cw-progress">
                  <div class="gdi-cw-bar">
                    <div class="gdi-cw-fill" style="width:${progress}%"></div>
                  </div>
                  <span class="gdi-cw-time">${fmt(item.currentTime)} / ${fmt(item.duration)}</span>
                </div>
              </div>
              <button class="gdi-btn gdi-btn-sm gdi-btn-primary" onclick="resumeVideo('${item.videoId}')">
                Retomar
              </button>
            </div>
          `;
        }).join('')}
      </div>
    </div>
  `;
}

// ============================================================
// 4. SALVAMENTO AUTOMÁTICO DE PROGRESSO
// ============================================================

const AutoSaveProgress = (() => {
  let saveTimer = null;
  let currentPlayer = null;
  let currentVideoId = null;
  let lastSaveTime = 0;
  const SAVE_INTERVAL = 5000; // 5 segundos

  function init(videoId, player, fileName) {
    currentVideoId = videoId;
    currentPlayer = player;

    // Salvar ao pausar
    if (player.addEventListener) {
      player.addEventListener('pause', saveProgress);
      player.addEventListener('ended', saveProgressOnEnd);
    }

    // Salvamento automático a cada 5 segundos durante reprodução
    if (saveTimer) clearInterval(saveTimer);
    saveTimer = setInterval(() => {
      if (currentPlayer && !currentPlayer.paused) {
        saveProgress();
      }
    }, SAVE_INTERVAL);
  }

  function saveProgress() {
    const now = Date.now();
    if (now - lastSaveTime < 1000) return; // Evitar spam
    lastSaveTime = now;

    if (!currentPlayer || !currentVideoId) return;

    let currentTime = 0;
    let duration = 0;

    // Obter tempo do player
    if (typeof currentPlayer.currentTime === 'number') {
      currentTime = currentPlayer.currentTime;
    } else if (typeof currentPlayer.currentTime === 'function') {
      currentTime = currentPlayer.currentTime();
    }

    if (typeof currentPlayer.duration === 'number') {
      duration = currentPlayer.duration;
    } else if (typeof currentPlayer.duration === 'function') {
      duration = currentPlayer.duration();
    }

    if (currentTime > 0 && duration > 0) {
      GDIUserSystem.saveVideoProgress(
        currentVideoId,
        currentTime,
        duration,
        currentPlayer.title || 'Vídeo'
      );
    }
  }

  function saveProgressOnEnd() {
    if (currentPlayer && currentVideoId) {
      GDIUserSystem.saveVideoProgress(
        currentVideoId,
        0,
        currentPlayer.duration || 0,
        currentPlayer.title || 'Vídeo'
      );
    }
  }

  function cleanup() {
    if (saveTimer) {
      clearInterval(saveTimer);
      saveTimer = null;
    }
  }

  return {
    init,
    cleanup,
    saveProgress
  };
})();

// ============================================================
// 5. MODO SLEEP APRIMORADO PARA ÁUDIO
// ============================================================

function initAudioSleepMode() {
  const existing = document.getElementById('gdi-sleep-overlay');
  if (existing) existing.remove();
  const existingBtn = document.getElementById('gdi-sleep-btn');
  if (existingBtn) existingBtn.remove();

  const overlay = document.createElement('div');
  overlay.id = 'gdi-sleep-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:8000;background:#000;opacity:0;pointer-events:none;transition:opacity 3s ease;cursor:pointer;';
  overlay.title = 'Clique para sair do modo descanso';
  document.body.appendChild(overlay);

  const btn = document.createElement('button');
  btn.id = 'gdi-sleep-btn';
  btn.innerHTML = '<i class="bi bi-moon-stars-fill"></i>';
  btn.title = 'Modo descanso';
  btn.style.cssText = 'position:fixed;bottom:76px;left:16px;z-index:8001;background:rgba(18,18,28,0.92);border:1.5px solid rgba(255,255,255,0.15);border-radius:50%;width:40px;height:40px;color:#74c0fc;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 14px rgba(0,0,0,0.5);';
  document.body.appendChild(btn);

  let sleeping = false;
  let fadeTimer = null;
  const FADE_DELAY = 8000;
  const FADE_TARGET = 0.97;

  function enterSleep() {
    if (sleeping) return;
    sleeping = true;
    overlay.style.pointerEvents = 'all';
    overlay.style.opacity = String(FADE_TARGET);
    btn.innerHTML = '<i class="bi bi-sun-fill"></i>';
    btn.style.color = '#ffd43b';
    btn.title = 'Sair do modo descanso';
  }

  function exitSleep() {
    sleeping = false;
    overlay.style.opacity = '0';
    overlay.style.pointerEvents = 'none';
    btn.innerHTML = '<i class="bi bi-moon-stars-fill"></i>';
    btn.style.color = '#74c0fc';
    btn.title = 'Modo descanso';
    clearTimeout(fadeTimer);
  }

  function scheduleSleep() {
    clearTimeout(fadeTimer);
    fadeTimer = setTimeout(enterSleep, FADE_DELAY);
  }

  function cancelSleep() {
    clearTimeout(fadeTimer);
    if (sleeping) exitSleep();
  }

  overlay.addEventListener('click', exitSleep);
  btn.addEventListener('click', () => {
    sleeping ? exitSleep() : enterSleep();
  });

  ['mousemove', 'keydown', 'touchstart'].forEach(ev => {
    document.addEventListener(ev, () => {
      if (sleeping) {
        exitSleep();
        const ap = window._gdiAPlayer;
        if (ap && !ap.audio.paused) {
          scheduleSleep();
        }
      }
    }, { passive: true });
  });

  function connectAPlayer() {
    const ap = window._gdiAPlayer;
    if (!ap) return;
    ap.on('play', () => {
      scheduleSleep();
    });
    ap.on('pause', () => {
      cancelSleep();
    });
    ap.on('ended', () => {
      cancelSleep();
    });
  }

  let tries = 0;
  const wait = setInterval(() => {
    if (window._gdiAPlayer) {
      clearInterval(wait);
      connectAPlayer();
    }
    if (++tries > 50) clearInterval(wait);
  }, 100);
}

